function lockLearnerApis(){for(const key of ['indexedDB','caches','fetch','XMLHttpRequest','WebSocket','EventSource','WebTransport','Worker','SharedWorker','BroadcastChannel','importScripts']){let o=self;while(o){try{const d=Object.getOwnPropertyDescriptor(o,key);if(d?.configurable)delete o[key]}catch{}o=Object.getPrototypeOf(o)}try{Object.defineProperty(self,key,{value:undefined,writable:false,configurable:false})}catch{}}}
/* Each JavaScript run gets a new worker and a hard termination timer in the parent. */
self.onmessage=e=>{const {code,id}=e.data;lockLearnerApis();const output=[];const console={log:(...args)=>output.push(args.map(x=>typeof x==='string'?x:JSON.stringify(x)).join(' '))};try{if(typeof code!=='string'||code.length>12000)throw Error('Programme trop long.');new Function('console',code)(console);postMessage({id,output:output.join('\n'),done:true})}catch(error){postMessage({id,error:'Vérifie la syntaxe et les noms de tes variables.\n'+String(error.message)})}};
